// Types and links for the "All lines" view. The data itself is generated by
// scripts/build-network.mjs into network.json and served by /api/network.

export interface NetworkVariant {
  headsign: string;
  /** Trips per day on the scanned dates; the first variant is the busiest. */
  trips: number;
  stops: string[];
  /** Simplified [lon, lat] line. */
  shape: [number, number][];
}

export interface NetworkLine {
  route: string;
  color: string;
  textColor: string;
  variants: NetworkVariant[];
}

export interface NetworkResponse {
  generatedAt: string;
  lines: NetworkLine[];
  /** Stop id → [name, lat, lon] for every stop on the network. */
  stops: Record<string, [string, number, number]>;
}

/** Marprom's official network diagram (large PDF, ~20 MB). */
export const NETWORK_PDF = 'https://www.marprom.si/dokumentacija/shema-linij.pdf';
/** Marprom's map of a single line (PDF, a few MB). */
export const linePdf = (route: string) => `https://www.marprom.si/dokumentacija/prikaz-linij/september2026/${route.toUpperCase()}.pdf`;
